ALTER TYPE "WaitlistStatus" ADD VALUE IF NOT EXISTS 'MATCHED';
ALTER TYPE "WaitlistStatus" ADD VALUE IF NOT EXISTS 'CONVERTED';
ALTER TYPE "WaitlistStatus" ADD VALUE IF NOT EXISTS 'CLOSED';
CREATE TYPE "ChatbotEscalationSeverity" AS ENUM ('HIGH','CRITICAL');
CREATE TYPE "ChatbotEscalationStatus" AS ENUM ('NEW','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','DISMISSED');
CREATE TYPE "NotificationPriority" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "InventoryCategory" AS ENUM ('MATERIAL','MEDICINE','CONSUMABLE','EQUIPMENT_SUPPLY','OTHER');
CREATE TYPE "InventoryProposalStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','MORE_INFO_REQUIRED','CANCELLED');
CREATE TYPE "InventoryOrderStatus" AS ENUM ('REQUESTED','PENDING_APPROVAL','APPROVED','REJECTED','ORDERED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED');
CREATE TYPE "InventoryOrderUrgency" AS ENUM ('NORMAL','URGENT');
CREATE TYPE "InventoryExpectedDeliveryUnit" AS ENUM ('HOURS','DAYS');
CREATE TYPE "StockTransactionType" AS ENUM ('RECEIPT','ADJUSTMENT');
ALTER TABLE "organization_settings" ADD COLUMN "check_in_before_mins" INTEGER NOT NULL DEFAULT 120, ADD COLUMN "check_in_after_mins" INTEGER NOT NULL DEFAULT 240;

ALTER TABLE "waitlist_entries" ADD COLUMN "converted_appointment_id" UUID, ADD COLUMN "created_by_user_id" UUID, ADD COLUMN "priority_reason" VARCHAR(500);
UPDATE "waitlist_entries" SET "priority"=CASE WHEN "priority"<=0 THEN 2 WHEN "priority">4 THEN 4 ELSE "priority" END;
UPDATE "waitlist_entries" SET "priority_reason"='Migrated legacy scheduling priority' WHERE "priority">=3 AND "priority_reason" IS NULL;
ALTER TABLE "waitlist_entries" ALTER COLUMN "priority" SET DEFAULT 2,
 ADD CONSTRAINT "waitlist_priority_range" CHECK ("priority" BETWEEN 1 AND 4),
 ADD CONSTRAINT "waitlist_priority_reason_required" CHECK ("priority"<3 OR NULLIF(BTRIM("priority_reason"),'') IS NOT NULL),
 ADD CONSTRAINT "waitlist_converted_appointment_fkey" FOREIGN KEY ("organization_id","converted_appointment_id") REFERENCES "appointments"("organization_id","id") ON DELETE RESTRICT,
 ADD CONSTRAINT "waitlist_creator_fkey" FOREIGN KEY ("created_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL;
CREATE UNIQUE INDEX "waitlist_converted_appointment_key" ON "waitlist_entries"("organization_id","converted_appointment_id");

CREATE TABLE "waitlist_history" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"waitlist_entry_id" UUID NOT NULL,"from_status" "WaitlistStatus","to_status" "WaitlistStatus" NOT NULL,"reason" VARCHAR(500),"actor_user_id" UUID,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","waitlist_entry_id") REFERENCES "waitlist_entries"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("actor_user_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "waitlist_history_org_id_key" ON "waitlist_history"("organization_id","id"); CREATE INDEX "waitlist_history_entry_idx" ON "waitlist_history"("organization_id","waitlist_entry_id","created_at");

CREATE TABLE "chatbot_escalations" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"branch_id" UUID,"customer_id" UUID,"appointment_id" UUID,"conversation_id" UUID,"patient_name" VARCHAR(160) NOT NULL,"phone" VARCHAR(40),"email" VARCHAR(320),"emergency_summary" TEXT NOT NULL,"relevant_message" TEXT NOT NULL,"source_channel" "CommunicationChannel" NOT NULL,"severity" "ChatbotEscalationSeverity" NOT NULL,"status" "ChatbotEscalationStatus" NOT NULL DEFAULT 'NEW',"assigned_membership_id" UUID,"assigned_user_id" UUID,"source_action_id" UUID,"acknowledged_at" TIMESTAMPTZ(3),"resolved_at" TIMESTAMPTZ(3),"resolution_note" TEXT,"version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,
 FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","branch_id") REFERENCES "branches"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("organization_id","customer_id") REFERENCES "customers"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("organization_id","appointment_id") REFERENCES "appointments"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("organization_id","conversation_id") REFERENCES "conversations"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("organization_id","assigned_membership_id") REFERENCES "organization_memberships"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("assigned_user_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "chatbot_escalations_org_id_key" ON "chatbot_escalations"("organization_id","id"); CREATE UNIQUE INDEX "chatbot_escalations_action_key" ON "chatbot_escalations"("organization_id","source_action_id"); CREATE INDEX "chatbot_escalations_queue_idx" ON "chatbot_escalations"("organization_id","status","severity","created_at");

CREATE TABLE "chatbot_escalation_history" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"escalation_id" UUID NOT NULL,"from_status" "ChatbotEscalationStatus","to_status" "ChatbotEscalationStatus" NOT NULL,"reason" TEXT,"actor_user_id" UUID,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","escalation_id") REFERENCES "chatbot_escalations"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("actor_user_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "chatbot_escalation_history_org_id_key" ON "chatbot_escalation_history"("organization_id","id"); CREATE INDEX "chatbot_escalation_history_parent_idx" ON "chatbot_escalation_history"("organization_id","escalation_id","created_at");

CREATE TABLE "notifications" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"branch_id" UUID,"recipient_user_id" UUID NOT NULL,"type" VARCHAR(80) NOT NULL,"title_en" VARCHAR(160) NOT NULL,"title_ar" VARCHAR(160) NOT NULL,"message_en" VARCHAR(300) NOT NULL,"message_ar" VARCHAR(300) NOT NULL,"related_entity_type" VARCHAR(80),"related_entity_id" UUID,"target_route" VARCHAR(500) NOT NULL,"priority" "NotificationPriority" NOT NULL DEFAULT 'NORMAL',"read_at" TIMESTAMPTZ(3),"done_at" TIMESTAMPTZ(3),"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "notifications_done_after_read" CHECK ("done_at" IS NULL OR "read_at" IS NOT NULL), FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","branch_id") REFERENCES "branches"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("recipient_user_id") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "notifications_org_id_key" ON "notifications"("organization_id","id"); CREATE INDEX "notifications_recipient_idx" ON "notifications"("organization_id","recipient_user_id","done_at","read_at","created_at");

CREATE TABLE "inventory_items" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"name" VARCHAR(160) NOT NULL,"category" "InventoryCategory" NOT NULL,"unit_of_measure" VARCHAR(40) NOT NULL,"current_stock" DECIMAL(14,3) NOT NULL DEFAULT 0,"minimum_stock" DECIMAL(14,3) NOT NULL DEFAULT 0,"supplier_name" VARCHAR(160),"supplier_phone" VARCHAR(40),"unit_price" DECIMAL(14,3),"currency" CHAR(3) NOT NULL DEFAULT 'JOD',"is_active" BOOLEAN NOT NULL DEFAULT TRUE,"notes" TEXT,"created_by_user_id" UUID NOT NULL,"approved_by_user_id" UUID,"version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,
 CHECK ("current_stock">=0 AND "minimum_stock">=0), FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","branch_id") REFERENCES "branches"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("created_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT, FOREIGN KEY ("approved_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "inventory_items_org_id_key" ON "inventory_items"("organization_id","id"); CREATE UNIQUE INDEX "inventory_items_branch_name_key" ON "inventory_items"("organization_id","branch_id","name");

CREATE TABLE "inventory_item_proposals" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"proposed_name" VARCHAR(160) NOT NULL,"category" "InventoryCategory" NOT NULL,"unit_of_measure" VARCHAR(40) NOT NULL,"reason_needed" TEXT NOT NULL,"suggested_quantity" DECIMAL(14,3) NOT NULL,"urgent" BOOLEAN NOT NULL DEFAULT FALSE,"note" TEXT,"status" "InventoryProposalStatus" NOT NULL DEFAULT 'PENDING_APPROVAL',"created_by_user_id" UUID NOT NULL,"reviewed_by_user_id" UUID,"review_note" TEXT,"created_item_id" UUID,"version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,
 CHECK ("suggested_quantity">0), FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","branch_id") REFERENCES "branches"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("created_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT, FOREIGN KEY ("reviewed_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "inventory_proposals_org_id_key" ON "inventory_item_proposals"("organization_id","id"); CREATE INDEX "inventory_proposals_queue_idx" ON "inventory_item_proposals"("organization_id","branch_id","status","urgent","created_at");

CREATE TABLE "inventory_order_requests" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"item_id" UUID NOT NULL,"requested_quantity" DECIMAL(14,3) NOT NULL,"received_quantity" DECIMAL(14,3) NOT NULL DEFAULT 0,"ordered_quantity" DECIMAL(14,3),"urgency" "InventoryOrderUrgency" NOT NULL DEFAULT 'NORMAL',"reason" TEXT NOT NULL,"note" TEXT,"status" "InventoryOrderStatus" NOT NULL DEFAULT 'PENDING_APPROVAL',"requested_by_user_id" UUID NOT NULL,"reviewed_by_user_id" UUID,"review_note" TEXT,"ordered_by_user_id" UUID,"supplier_name" VARCHAR(160),"supplier_reference" VARCHAR(160),"ordered_at" TIMESTAMPTZ(3),"expected_delivery_value" INTEGER,"expected_delivery_unit" "InventoryExpectedDeliveryUnit","expected_arrival_at" TIMESTAMPTZ(3),"version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,
 CHECK ("requested_quantity">0 AND "received_quantity">=0 AND ("ordered_quantity" IS NULL OR "ordered_quantity">0) AND "received_quantity"<=COALESCE("ordered_quantity","requested_quantity")), FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","branch_id") REFERENCES "branches"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("organization_id","item_id") REFERENCES "inventory_items"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("requested_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT, FOREIGN KEY ("reviewed_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL, FOREIGN KEY ("ordered_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "inventory_orders_org_id_key" ON "inventory_order_requests"("organization_id","id"); CREATE INDEX "inventory_orders_queue_idx" ON "inventory_order_requests"("organization_id","branch_id","status","urgency","created_at"); CREATE INDEX "inventory_orders_eta_idx" ON "inventory_order_requests"("organization_id","expected_arrival_at","status");

CREATE TABLE "stock_transactions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"item_id" UUID NOT NULL,"order_request_id" UUID,"type" "StockTransactionType" NOT NULL,"quantity" DECIMAL(14,3) NOT NULL,"resulting_stock" DECIMAL(14,3) NOT NULL,"request_key" UUID NOT NULL,"request_fingerprint" CHAR(64) NOT NULL,"note" TEXT,"recorded_by_user_id" UUID NOT NULL,"received_at" TIMESTAMPTZ(3) NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK ("quantity">0 AND "resulting_stock">=0), FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE, FOREIGN KEY ("organization_id","branch_id") REFERENCES "branches"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("organization_id","item_id") REFERENCES "inventory_items"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("organization_id","order_request_id") REFERENCES "inventory_order_requests"("organization_id","id") ON DELETE RESTRICT, FOREIGN KEY ("recorded_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "stock_transactions_org_id_key" ON "stock_transactions"("organization_id","id"); CREATE UNIQUE INDEX "stock_transactions_request_key" ON "stock_transactions"("organization_id","request_key"); CREATE INDEX "stock_transactions_item_idx" ON "stock_transactions"("organization_id","item_id","created_at");

INSERT INTO "permissions" ("id","code","name_en","name_ar") SELECT gen_random_uuid(),code,en,ar FROM (VALUES
('chatbot.checkin.execute','Run verified chatbot check-in','تنفيذ تسجيل الوصول الموثق عبر المحادثة'),('chatbot_escalations.read','Read chatbot escalations','عرض تصعيدات المساعد الآلي'),('chatbot_escalations.manage','Manage chatbot escalations','إدارة تصعيدات المساعد الآلي'),('notifications.read','Read notifications','عرض الإشعارات'),('notifications.manage','Manage notifications','إدارة الإشعارات'),('inventory.items.read','Read inventory availability','عرض توفر المخزون'),('inventory.items.createDirect','Create inventory items directly','إنشاء أصناف المخزون مباشرة'),('inventory.itemProposal.create','Request new inventory items','طلب أصناف مخزون جديدة'),('inventory.itemProposal.approve','Approve inventory item proposals','الموافقة على مقترحات أصناف المخزون'),('inventory.orderRequest.create','Create inventory order requests','إنشاء طلبات توريد المخزون'),('inventory.orderRequest.approve','Approve inventory order requests','الموافقة على طلبات توريد المخزون'),('inventory.order.markOrdered','Mark inventory orders placed','تسجيل طلبات المخزون كطلبات مورّد'),('inventory.order.receive','Receive inventory orders','استلام طلبات المخزون'),('inventory.supplier.read','Read inventory supplier details','عرض تفاصيل موردي المخزون'),('inventory.cost.read','Read inventory costs','عرض تكاليف المخزون'),('inventory.stock.adjust','Adjust inventory stock','تعديل رصيد المخزون')) p(code,en,ar) ON CONFLICT ("code") DO NOTHING;

WITH g AS (SELECT r."organization_id",r."id" role_id,p."id" permission_id FROM "roles" r CROSS JOIN "permissions" p WHERE r."system_key"='ORGANIZATION_OWNER' AND (p."code" LIKE 'inventory.%' OR p."code" LIKE 'chatbot_escalations.%' OR p."code" LIKE 'notifications.%')) INSERT INTO "role_permissions"("organization_id","role_id","permission_id","scope") SELECT "organization_id",role_id,permission_id,'ORGANIZATION'::"PermissionScope" FROM g ON CONFLICT DO NOTHING;
WITH g(code,scope) AS (VALUES ('notifications.read','SELF'::"PermissionScope"),('inventory.items.read','ASSIGNED_BRANCHES'::"PermissionScope"),('inventory.itemProposal.create','SELF'::"PermissionScope"),('inventory.orderRequest.create','SELF'::"PermissionScope")) INSERT INTO "role_permissions"("organization_id","role_id","permission_id","scope") SELECT r."organization_id",r."id",p."id",g.scope FROM g JOIN "permissions" p ON p."code"=g.code JOIN "roles" r ON r."system_key"='PROVIDER' ON CONFLICT DO NOTHING;

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['waitlist_history','chatbot_escalations','chatbot_escalation_history','notifications','inventory_items','inventory_item_proposals','inventory_order_requests','stock_transactions'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I ON %I USING (organization_id=NULLIF(CURRENT_SETTING(''app.organization_id'',true),'''')::uuid) WITH CHECK (organization_id=NULLIF(CURRENT_SETTING(''app.organization_id'',true),'''')::uuid)',t||'_tenant_isolation',t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO jormall_app',t); END LOOP; END $$;
DROP POLICY "notifications_tenant_isolation" ON "notifications";
CREATE POLICY "notifications_select_own" ON "notifications" FOR SELECT USING ("organization_id"=NULLIF(CURRENT_SETTING('app.organization_id',true),'')::uuid AND "recipient_user_id"=NULLIF(CURRENT_SETTING('app.actor_user_id',true),'')::uuid);
CREATE POLICY "notifications_insert_tenant" ON "notifications" FOR INSERT WITH CHECK ("organization_id"=NULLIF(CURRENT_SETTING('app.organization_id',true),'')::uuid);
CREATE POLICY "notifications_update_own" ON "notifications" FOR UPDATE USING ("organization_id"=NULLIF(CURRENT_SETTING('app.organization_id',true),'')::uuid AND "recipient_user_id"=NULLIF(CURRENT_SETTING('app.actor_user_id',true),'')::uuid) WITH CHECK ("organization_id"=NULLIF(CURRENT_SETTING('app.organization_id',true),'')::uuid AND "recipient_user_id"=NULLIF(CURRENT_SETTING('app.actor_user_id',true),'')::uuid);
CREATE FUNCTION "reject_remaining_work_append_only_change"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'APPEND_ONLY_RECORD'; END; $$;
CREATE TRIGGER "waitlist_history_append_only" BEFORE UPDATE OR DELETE ON "waitlist_history" FOR EACH ROW EXECUTE FUNCTION "reject_remaining_work_append_only_change"(); CREATE TRIGGER "escalation_history_append_only" BEFORE UPDATE OR DELETE ON "chatbot_escalation_history" FOR EACH ROW EXECUTE FUNCTION "reject_remaining_work_append_only_change"(); CREATE TRIGGER "stock_transactions_append_only" BEFORE UPDATE OR DELETE ON "stock_transactions" FOR EACH ROW EXECUTE FUNCTION "reject_remaining_work_append_only_change"();
